import { tracer } from "./tracing";

export async function handleCheckout(request: Request): Promise<Response> {
    const span = tracer.startSpan("checkout");
    span.setAttribute("service", "orders-api");
    span.setAttribute("route", "/checkout");
    span.setAttribute("requestId", request.headers.get("x-request-id") ?? "unknown");
    try {
        return await processCheckout(request);
    } catch (error) {
        span.recordException(error);
        throw error;
    } finally {
        span.end();
    }
}
